export const getInputAsCodePoints = (src: ValidInput): number[] => {
  if (typeof src !== 'string') {
    return Array.isArray(src) ? src : [src,];
  }

  return src.split('').map((char) => {
    const codePoint = char.codePointAt(0);
    if (codePoint === undefined) {
