  parseAlternates = (
    rule_name: string,
    rule_id: number,
    depth = 0,
  ): void => {
    const src = this.src;
    const rule: InternalRuleDef[] = [];
    this.parseSequence(rule_name, rule, depth);
    while (src[this.pos] === '|') {
