def parse_space(src: str, pos: int, newline_ok: bool) -> int:
    n = len(src)
    while pos < n and (src[pos] in " \t#" or (newline_ok and src[pos] in "\r\n")):
        if src[pos] == "#":
            while pos < n and src[pos] not in "\r\n":
                pos += 1
        else:
            pos += 1
    return pos
