from ..utils.errors.grammar_parse_error import GrammarParseError

_HEX_DIGITS = "0123456789abcdefABCDEF"


def _parse_hex(src: str, pos: int, value: str) -> int:
    # mirrors parseInt(value, 16): parse the longest valid hex prefix
    digits = ""
    for c in value:
        if c not in _HEX_DIGITS:
            break
        digits += c
    if not digits:
        raise GrammarParseError(src, pos, f"Invalid hex escape: {value}")
    return int(digits, 16)


def parse_char(src: str, pos: int) -> tuple[int, int]:
    char = src[pos] if pos < len(src) else ""
    if char == "\\":
        nxt = src[pos + 1] if pos + 1 < len(src) else ""
        if nxt == "x":
            return _parse_hex(src, pos, src[pos + 2 : pos + 4]), 4
        if nxt == "u":
            return _parse_hex(src, pos, src[pos + 2 : pos + 6]), 6
        if nxt == "U":
            return _parse_hex(src, pos, src[pos + 2 : pos + 10]), 10
        if nxt == "t":
            return ord("\t"), 2
        if nxt == "r":
            return ord("\r"), 2
        if nxt == "n":
            return ord("\n"), 2
        if nxt in {'"', "[", "]", "\\"}:
            return ord(nxt), 2
        raise GrammarParseError(src, pos, f"Unknown escape at {char}")

    if not char:
        raise GrammarParseError(src, pos, "Unexpected end of grammar input, failed to complete parse")
    return ord(char), 1
