from __future__ import annotations

from enum import Enum
from typing import Union


class RuleType(str, Enum):
    CHAR = "char"
    CHAR_EXCLUDE = "char_exclude"
    END = "end"

    def __str__(self) -> str:
        return self.value


Range = list[int]  # [start, end]


class _RuleWithValue:
    type: RuleType

    def __init__(self, value: list[int | Range]):
        self.type = self.__class__.type
        self.value = value

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, _RuleWithValue):
            return NotImplemented
        return self.type == other.type and self.value == other.value

    __hash__ = None  # type: ignore[assignment]

    def __repr__(self) -> str:
        return f"{self.__class__.__name__}({self.value!r})"


class RuleChar(_RuleWithValue):
    type = RuleType.CHAR


class RuleCharExclude(_RuleWithValue):
    type = RuleType.CHAR_EXCLUDE


class RuleEnd:
    type = RuleType.END

    def __init__(self) -> None:
        self.type = RuleType.END

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, RuleEnd):
            return NotImplemented
        return True

    __hash__ = None  # type: ignore[assignment]

    def __repr__(self) -> str:
        return "RuleEnd()"


ResolvedRule = Union[RuleChar, RuleCharExclude, RuleEnd]  # noqa: UP007

# ValidInput can either be a string, or a number indicating a code point.
# It CANNOT be a number representing a number; a number being a "number" (like "8")
# should be passed in as a string.
ValidInput = Union[str, int, list[int]]  # noqa: UP007
