from __future__ import annotations

from collections.abc import Iterator

from ..utils.errors.input_parse_error import InputParseError
from ..utils.is_point_in_range import is_point_in_range
from .colorize import colorize, no_colorize
from .generic_set import GenericSet
from .get_input_as_code_points import get_input_as_code_points
from .get_serialized_rule_key import get_serialized_rule_key
from .graph_node import GraphNode, GraphNodeMeta
from .graph_pointer import GraphPointer
from .rule_ref import RuleRef
from .type_guards import is_range, is_rule_char, is_rule_char_excluded, is_rule_end, is_rule_ref
from .types import ValidInput

RootNode = dict[int, GraphNode]
Pointers = GenericSet[GraphPointer, str]


def make_pointers() -> Pointers:
    return GenericSet(lambda p: p.id)


class Graph:
    def __init__(self, grammar: str, stacked_rules: list[list[list]], root_id: int):
        self.grammar = grammar
        self.roots: dict[int, RootNode] = {}
        self.previous_code_points: list[int] = []
        rule_refs: list[RuleRef] = []
        unique_rules = GenericSet(get_serialized_rule_key)
        for stack_id, stack in enumerate(stacked_rules):
            nodes: RootNode = {}
            for path_id, path in enumerate(stack):
                node: GraphNode | None = None
                for step_id in range(len(path) - 1, -1, -1):
                    next_node = node
                    rule = path[step_id]
                    unique_rules.add(rule)
                    if is_rule_ref(rule):
                        rule_refs.append(rule)
                    # rules coming in may be identical but have different references.
                    # here, we ensure we always use the same reference for an identical rule.
                    # this makes future comparisons easier.
                    unique_rule = unique_rules.get(rule)
                    if unique_rule is None:
                        raise ValueError("Could not get unique rule")
                    node = GraphNode(unique_rule, GraphNodeMeta(stack_id, path_id, step_id), next_node)
                if node is None:
                    raise ValueError("Could not get node")
                nodes[path_id] = node
            self.roots[stack_id] = nodes

        root_node = self.roots.get(root_id)
        if root_node is None:
            raise ValueError(f"Root node not found for value: {root_id}")
        self._root_node = root_node

        for rule_ref in rule_refs:
            rule_ref.nodes = list(self._get_root_node(rule_ref.value).values())

    def _get_root_node(self, value: int) -> RootNode:
        root_node = self.roots.get(value)
        if root_node is None:
            raise ValueError(f"Root node not found for value: {value}")
        return root_node

    def _get_initial_pointers(self) -> Pointers:
        pointers = make_pointers()
        for node, parent in self._fetch_nodes_for_root_node(self._root_node):
            pointer = GraphPointer(node, parent)
            for resolved_pointer in self._resolve_pointer(pointer):
                pointers.add(resolved_pointer)
        return pointers

    @staticmethod
    def _set_valid(pointers: list[GraphPointer], valid: bool) -> None:
        for pointer in pointers:
            pointer.valid = valid

    def _parse(self, current_pointers: Pointers, code_point: int) -> Pointers:
        for rule, graph_pointers in self._iterate_over_pointers(current_pointers):
            if is_rule_char(rule):
                valid = any(
                    is_point_in_range(code_point, possible) if is_range(possible) else code_point == possible
                    for possible in rule.value
                )
                self._set_valid(graph_pointers, valid)
            elif is_rule_char_excluded(rule):
                valid = all(
                    not is_point_in_range(code_point, possible) if is_range(possible) else code_point != possible
                    for possible in rule.value
                )
                self._set_valid(graph_pointers, valid)
            elif not is_rule_end(rule):
                raise ValueError(f"Unsupported rule: {rule!r}")

        # a pointer's id is the sum of its node's id and its parent's id chain.
        # if two pointers share the same id, it means they point to the same node and have identical parent
        # chains. for the purposes of walking the graph, we only need to keep one of them.
        next_pointers = make_pointers()
        for current_pointer in current_pointers:
            for unresolved_next_pointer in current_pointer.fetch_next():
                for resolved_next_pointer in self._resolve_pointer(unresolved_next_pointer):
                    next_pointers.add(resolved_next_pointer)
        return next_pointers

    @staticmethod
    def _resolve_pointer(unresolved_pointer: GraphPointer) -> Iterator[GraphPointer]:
        for resolved_pointer in unresolved_pointer.resolve():
            if is_rule_ref(resolved_pointer.node.rule):
                raise ValueError("Encountered a reference rule when building pointers to the graph")
            if is_rule_end(resolved_pointer.node.rule) and resolved_pointer.parent is not None:
                raise ValueError("Encountered an ending rule with a parent when building pointers to the graph")
            yield resolved_pointer

    def add(self, src: ValidInput, _pointers: Pointers | None = None) -> Pointers:
        pointers = _pointers if _pointers is not None else self._get_initial_pointers()
        code_points = get_input_as_code_points(src)
        for code_point_pos, code_point in enumerate(code_points):
            pointers = self._parse(pointers, code_point)
            if pointers.size == 0:
                raise InputParseError(code_points, code_point_pos, list(self.previous_code_points))
        self.previous_code_points.extend(code_points)
        return pointers

    # generator that yields either the node, or if a reference rule, the referenced node
    # we need this function, as distinct from leveraging the logic in GraphPointer,
    # because that needs a rule ref with already defined nodes; this function is used to _set_ those nodes
    def _fetch_nodes_for_root_node(
        self, root_nodes: RootNode, parent: GraphPointer | None = None,
    ) -> Iterator[tuple[GraphNode, GraphPointer | None]]:
        for node in root_nodes.values():
            if is_rule_ref(node.rule):
                yield from self._fetch_nodes_for_root_node(
                    self._get_root_node(node.rule.value), GraphPointer(node, parent),
                )
            else:
                yield node, parent

    def print(self, pointers: Pointers | None = None, colors: bool = False) -> str:
        col = colorize if colors else no_colorize
        graph_view = [
            node.print(col, pointers=pointers, show_position=True)
            for nodes in self.roots.values()
            for node in nodes.values()
        ]
        return "\n" + "\n".join(graph_view)

    def __str__(self) -> str:
        return self.print(colors=True)

    @staticmethod
    def _iterate_over_pointers(pointers: Pointers) -> Iterator[tuple[object, list[GraphPointer]]]:
        seen_rules: dict[int, tuple[object, list[GraphPointer]]] = {}
        for pointer in pointers:
            rule = pointer.rule
            if is_rule_ref(rule):
                raise ValueError("Encountered a reference rule in the graph, this should not happen")
            entry = seen_rules.get(id(rule))
            if entry is None:
                seen_rules[id(rule)] = (rule, [pointer])
            else:
                entry[1].append(pointer)

        yield from seen_rules.values()
