from __future__ import annotations

import json
from collections.abc import Iterator
from typing import TYPE_CHECKING

if TYPE_CHECKING:
    from .graph import Graph, Pointers
    from .types import ResolvedRule, ValidInput


class ParseState:
    def __init__(self, graph: Graph, pointers: Pointers):
        self._graph = graph
        self._pointers = pointers

    def __call__(self, src: ValidInput) -> ParseState:
        return self.add(src)

    def __add__(self, src: ValidInput) -> ParseState:
        return self.add(src)

    def __iter__(self) -> Iterator[ResolvedRule]:
        yield from self.rules()

    def rules(self) -> Iterator[ResolvedRule]:
        seen: set[str] = set()
        for pointer in self._pointers:
            rule = pointer.rule
            key = json.dumps([rule.type.value, getattr(rule, "value", None)])
            if key not in seen:
                seen.add(key)
                yield rule

    def add(self, src: ValidInput) -> ParseState:
        pointers = self._graph.add(src, self._pointers)
        return ParseState(self._graph, pointers)

    @property
    def size(self) -> int:
        return len(list(self.rules()))

    @property
    def grammar(self) -> str:
        return self._graph.grammar

    def __bool__(self) -> bool:
        return True

    def __repr__(self) -> str:
        return f"ParseState({list(self.rules())!r})"
