CASES = json.loads((Path(__file__).parent / "grammars.json").read_text())


def unescape(s: str) -> str:
    return s.replace("\\n", "\n").replace("\\t", "\t")


def describe_grammars():
    @pytest.mark.parametrize(("name", "test_case", "grammar"), CASES)
    def test_it_parses_a_known_valid_grammar(name, test_case, grammar):
        state = GBNF(unescape(grammar))
        for char in unescape(test_case):
            state = state.add(char)
