import json, random, sys
rnd = random.Random(int(sys.argv[1]))
ALPH = "abc"
def lit():
    return '"' + "".join(rnd.choice(ALPH + "\\n") if rnd.random() < .1 else rnd.choice(ALPH) for _ in range(rnd.randint(1, 3))) + '"'
def cls():
    neg = "^" if rnd.random() < .3 else ""
    items = []
    for _ in range(rnd.randint(1, 3)):
        a = rnd.choice(ALPH + "xyz")
        items.append(a + "-" + chr(ord(a) + rnd.randint(0, 3)) if rnd.random() < .4 else a)
    return "[" + neg + "".join(items) + "]"
def term(names, d):
    r = rnd.random()
    if r < .35: t = lit()
    elif r < .6: t = cls()
    elif r < .8 and names: t = rnd.choice(names)
    elif d < 2: t = "(" + alts(names, d + 1) + ")"
    else: t = lit()
    if rnd.random() < .3: t += rnd.choice("*+?")
    return t
def seq(names, d): return " ".join(term(names, d) for _ in range(rnd.randint(1, 3)))
def alts(names, d): return " | ".join(seq(names, d) for _ in range(rnd.randint(1, 3)))
cases = []
for _ in range(int(sys.argv[2])):
    names = ["root"] + ["r" + c for c in "abcd"[: rnd.randint(0, 3)]]
    g = "\n".join(f"{n} ::= {alts(names[i+1:] if rnd.random() < .7 else names, 0)}" for i, n in enumerate(names))
    if rnd.random() < .1:  # corrupt
        p = rnd.randrange(len(g)); g = g[:p] + rnd.choice(['"', "(", ")", "|", ":", "=", "\\", "[", "_", "1"]) + g[p:]
    inputs = ["".join(rnd.choice(ALPH + "xyz\n") for _ in range(rnd.randint(1, 2))) for _ in range(rnd.randint(1, 6))]
    cases.append([g, inputs])
print(json.dumps(cases))
