p='graph_pointer.py'; s=open(p).read()
start=s.index("    def resolve(self"); end=s.index("    @property\n    def rule")
new='''    def resolve(self, resolved: bool = False, max_depth: int | None = None) -> Iterator[GraphPointer]:
        """
        1. If the current node is an end node, and the pointer has a parent, return the parent's `fetch_next`;
           else return nothing.
        2. If the current node is a rule ref, yield the referenced nodes, _unless_ resolved is true, in which
           case it returns next.
        3. If the current node is a char or range, we go to the next node. If none exists, throw an error.

        This is implemented iteratively (rather than recursively) so that deeply nested parent chains, which
        arise from long repeated input, don't exhaust Python's recursion limit.

        `max_depth` bounds how many rule refs can be expanded on top of one another without consuming input.
        Exceeding it means the grammar is left-recursive (or otherwise expands forever); it defaults to
        the total number of nodes reachable in the graph, a depth no terminating expansion can exceed.
        """
        if max_depth is None:
            max_depth = _count_reachable_nodes(self.node)
        # each work item is (pointer, resolved, number of frames added on top of the starting pointer)
        stack: list[tuple[GraphPointer, bool, int]] = [(self, resolved, 0)]
        while stack:
            pointer, is_resolved, added = stack.pop()
            while True:
                rule = pointer.node.rule
                if is_rule_ref(rule):
                    if is_resolved:
                        if pointer.node.next is None:
                            raise ValueError(f"No next node: {pointer.node!r}")
                        pointer, is_resolved = GraphPointer(pointer.node.next, pointer.parent), False
                        continue
                    if added >= max_depth:
                        raise RecursionError("maximum recursion depth exceeded")
                    stack.extend((GraphPointer(node, pointer), False, added + 1) for node in reversed(rule.nodes))
                elif is_rule_end(rule):
                    if not pointer.parent:
                        yield pointer
                    else:
                        pointer, is_resolved, added = pointer.parent, True, added - 1
                        continue
                elif is_rule_char(rule) or is_rule_char_excluded(rule):
                    yield pointer
                else:
                    raise ValueError(f"Unknown rule: {rule!r}")
                break

    def fetch_next(self) -> Iterator[GraphPointer]:
        # if this pointer is invalid, then we don't return any new pointers
        if self._valid is False:
            return

        # if this pointer is an end node, we return the parent's next node. If no parent exists,
        # we return nothing, since it's the end of the line.
        pointer: GraphPointer | None = self
        while pointer is not None and is_rule_end(pointer.node.rule):
            pointer = pointer.parent
            if pointer is not None and pointer._valid is False:
                return
        if pointer is None:
            return
        if pointer.node.next is None:
            raise ValueError(f"No next node: {pointer.node!r}")
        yield from GraphPointer(pointer.node.next, pointer.parent).resolve()

'''
