''','''from .type_guards import is_rule_char, is_rule_char_excluded, is_rule_end, is_rule_ref

_reachable_node_counts: dict[int, int] = {}


def _count_reachable_nodes(start: GraphNode) -> int:
    """Count the graph nodes reachable from `start`, following both `next` links and rule references."""
    cached = _reachable_node_counts.get(id(start))
    if cached is not None:
        return cached
    seen: set[int] = set()
    todo = [start]
    while todo:
        node = todo.pop()
        if id(node) in seen:
            continue
        seen.add(id(node))
        if node.next is not None:
            todo.append(node.next)
        if is_rule_ref(node.rule):
            todo.extend(node.rule.nodes)
    return len(seen)
''')
